import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};


 const out='/tmp/legendgirl-final';await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/final',{recursive:true});const reports=[];
 async function shot(name){const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/'+name+'.png',Buffer.from(shot.result.data,'base64'));await writeFile('docs/diario-ia/qa-resultados/final/'+name+'.png',Buffer.from(shot.result.data,'base64'));}
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='NORMAL';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));})()`);
 for(let i=0;i<200;i++){if(await evaluate('Boolean(game.state.toyRoomInstance?.instance?.garden?.ready)'))break;await new Promise(r=>setTimeout(r,50));}
 for(const[name,width,height,mobile]of [['desktop',1280,800,false],['android',390,844,true],['paisagem',844,390,true]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});
  await evaluate(`(async()=>{game.setPaused(true);const {createGardenState}=await import('/src/js/garden/GardenSimulation.js');game.state.toyRoomInstance.instance.garden.state=createGardenState();})()`);
  for(const [label,seconds]of [['porta',0],['degrau',1.6],['chao',1.5]]){
   await evaluate(`(async()=>{const phase=game.state.toyRoomInstance.instance.garden,{stepGarden}=await import('/src/js/garden/GardenSimulation.js');for(let t=0;t<${seconds};t+=1/60)stepGarden(phase.state,{},1/60);phase.render();})()`);await shot(name+'-'+label);
  }
 }
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await evaluate('game.setPaused(false)');
 for(let attempt=0;attempt<3;attempt++){
  await evaluate(`(()=>{const phase=game.state.toyRoomInstance.instance.garden;phase.state.stage='RUNNING';Object.assign(phase.state.player,{x:720,y:850,onGround:false,support:null});})()`);
  await new Promise(r=>setTimeout(r,250));
  const early=await evaluate(`(()=>{const p=game.state.toyRoomInstance.instance.garden;return{stage:p.state.stage,time:p.state.time,music:p.audio.music.currentTime,paused:p.audio.music.paused,options:!document.querySelector('#gameover-overlay').classList.contains('hidden')};})()`);
  assert.equal(early.stage,'FALLING','Queda continua antes do menu');assert.ok(!early.paused&&!early.options,'Música toca e opções aguardam animação');
  await shot('queda-'+attempt);
  for(let i=0;i<160;i++){if(await evaluate("game.state.toyRoomInstance.instance.garden.state.stage==='GAME_OVER'"))break;await new Promise(r=>setTimeout(r,50));}
  const late=await evaluate(`(()=>{const p=game.state.toyRoomInstance.instance.garden;return{stage:p.state.stage,music:p.audio.music.currentTime,paused:p.audio.music.paused,retry:document.querySelector('#btn-retry').textContent,quit:document.querySelector('#btn-restart').textContent,easy:document.querySelector('#easy-mode-dialog').open,count:game.state.defeatCount};})()`);
  assert.equal(late.stage,'GAME_OVER');assert.ok(!late.paused&&late.music>early.music+.5,'Trilha continua na queda e no Game Over');assert.equal(late.retry,'Tentar novamente');assert.equal(late.quit,'Desistir');assert.equal(late.easy,attempt===2,'Oferta do fácil na terceira derrota');reports.push({attempt,early,late});await shot('opcoes-'+attempt);
  if(attempt<2){await evaluate("document.querySelector('#btn-retry').click()");await new Promise(r=>setTimeout(r,500));assert.equal(await evaluate('game.state.toyRoomInstance.instance.garden.state.stage'),'RUNNING');}
 }
 await evaluate("document.querySelector('#btn-accept-easy').click()");await new Promise(r=>setTimeout(r,550));assert.equal(await evaluate('game.state.toyRoomInstance.instance.garden.difficulty'),'EASY');assert.equal(await evaluate('game.state.toyRoomInstance.instance.garden.state.stage'),'RUNNING');
 await writeFile('docs/diario-ia/qa-resultados/final/resultado.json',JSON.stringify(reports,null,2));console.log('APROVADO: porta/escada/chão em três formatos, queda animada antes do menu, música contínua, Tentar novamente/Desistir e oferta EASY na terceira derrota.');
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
